/* prog40_bisection_root.c
 * Reimplementation of the original obfuscated binary.
 * Behaviour:
 *   - prints "NO_INPUT"   if no command‑line argument is given
 *   - prints "BAD_INPUT"  if the argument is not a non‑negative integer
 *   - prints "OUT_OF_RANGE" if the integer is larger than 1 000 000
 *   - otherwise prints sqrt(N) computed by bisection,
 *     formatted with six digits after the decimal point.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    /* ---------- argument handling ---------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long val = strtol(argv[1], &endptr, 10);

    /* reject non‑numeric input */
    if (endptr == argv[1] || *endptr != '\0')
        goto bad_input;

    /* reject overflow / underflow */
    if (errno == ERANGE || val > LONG_MAX || val < 0)
        goto bad_input;

    if (val < 0)               /* negative numbers are also bad */
        goto bad_input;

    if (val > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- bisection sqrt ---------- */
    double N = (double)val;
    double low  = 0.0;
    double high = N;               /* the original added a constant that is 0.0 */
    double mid  = 0.0;

    for (int i = 0; i < 60; ++i) {
        mid = (high - low) * 0.5 + low;   /* (high+low)/2, but written like the original */
        if (N < mid * mid)
            high = mid;
        else
            low = mid;
    }

    printf("%.6f\n", mid);
    return 0;

bad_input:
    puts("BAD_INPUT");
    return 0;
}
